     2	// PostToolUse(Edit|Write): keep generated types in sync with their sources.
     3	//   *.graphql      -> pnpm codegen (server resolvers + client documents)
     4	//   schema.prisma  -> prisma generate in the owning package
     5	import { existsSync } from 'node:fs';
     6	import path from 'node:path';
     7	import { feedback, projectDir, readInput, run, tail } from './lib.mjs';
     8	
     9	const input = await readInput();
    10	const file = input.tool_input?.file_path;
    11	const root = projectDir(input);
    12	if (!file) process.exit(0);
    13	const abs = path.resolve(root, file);
    14	if (path.relative(root, abs).startsWith('..') || abs.includes(`${path.sep}node_modules${path.sep}`))
    15	  process.exit(0);
    16	
    17	if (abs.endsWith('.graphql')) {
    18	  const r = run('pnpm', ['run', 'codegen'], root);
    19	  if (!r.ok)
    20	    feedback(`codegen failed after editing ${path.relative(root, abs)}:\n${tail(r.output, 40)}`);
    21	} else if (path.basename(abs) === 'schema.prisma') {
    22	  let dir = path.dirname(abs);
    23	  while (dir.startsWith(root) && !existsSync(path.join(dir, 'package.json')))
    24	    dir = path.dirname(dir);
    25	  const r = run('pnpm', ['exec', 'prisma', 'generate'], dir);
    26	  if (!r.ok) feedback(`prisma generate failed:\n${tail(r.output, 40)}`);
    27	}
