     1	#!/usr/bin/env node
     2	// PostToolUse(Edit|Write): prettier + eslint --fix on the edited file; remaining lint errors go
     3	// back to Claude (exit 2) so it fixes them in the same turn.
     4	import path from 'node:path';
     5	import { feedback, hasBin, projectDir, readInput, run } from './lib.mjs';
     6	
     7	const FORMAT = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|json|md|css|graphql|ya?ml)$/;
     8	const LINT = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs)$/;
     9	const SKIP = /(^|\/)(node_modules|dist|__generated__|gql|ai\/sessions)\//;
    10	
    11	const input = await readInput();
    12	const file = input.tool_input?.file_path;
    13	const root = projectDir(input);
    14	if (!file) process.exit(0);
    15	const rel = path.relative(root, path.resolve(root, file));
    16	if (rel.startsWith('..') || SKIP.test(rel) || !FORMAT.test(rel)) process.exit(0);
    17	if (!hasBin(root, 'prettier')) process.exit(0); // tooling not installed yet
    18	
    19	const fmt = run(
    20	  'pnpm',
    21	  ['exec', 'prettier', '--write', '--ignore-unknown', '--log-level', 'warn', rel],
    22	  root,
    23	);
    24	if (!fmt.ok) feedback(`prettier failed on ${rel} (likely a syntax error):\n${fmt.output}`);
    25	
    26	if (LINT.test(rel) && hasBin(root, 'eslint')) {
    27	  const lint = run('pnpm', ['exec', 'eslint', '--fix', '--no-warn-ignored', rel], root);
    28	  if (!lint.ok)
    29	    feedback(`eslint found problems in ${rel} that --fix could not resolve:\n${lint.output}`);
    30	}
