    95	      const upstreamError = WeatherstackError.safeParse(body);
    96	      if (upstreamError.success) {
    97	        const { code, type } = upstreamError.data.error ?? {};
    98	        return {
    99	          ok: false,
   100	          reason: 'UPSTREAM_ERROR',
   101	          detail: redact(`success:false code=${code ?? '?'} type=${type ?? '?'}`),
   102	        };
   103	      }
   104	
   105	      const parsed = WeatherstackSuccess.safeParse(body);
   106	      if (!parsed.success) {
   107	        const paths = parsed.error.issues.map((issue) => issue.path.join('.')).join(', ');
