    34	
    35	  const update = (field: keyof PropertyFormValues) => (value: string) => {
    36	    setValues((current) => ({ ...current, [field]: value }));
    37	    setErrors((current) => ({ ...current, [field]: undefined }));
    38	  };
    39	
    40	  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    41	    event.preventDefault();
    42	    setNotice(null);
    43	    const clientErrors = validateProperty(values);
    44	    setErrors(clientErrors);
    45	    if (Object.keys(clientErrors).length > 0) return;
    46	
    47	    try {
    48	      const { data } = await createProperty({
    49	        variables: { input: { ...values, state: values.state as USState } },
    50	      });
    51	      const result = data?.createProperty;
    52	      switch (result?.__typename) {
    53	        case 'CreatePropertySuccess':
    54	          toast.success('Property created', { description: values.street.trim() });
