    56	          return;
    57	        case 'InvalidInputError':
    58	          setErrors(
    59	            Object.fromEntries(result.fieldErrors.map(({ field, message }) => [field, message])),
    60	          );
    61	          return;
    62	        case 'DuplicatePropertyError':
    63	          setNotice({ kind: 'duplicate', ...result });
    64	          return;
    65	        case 'WeatherUnavailableError':
    66	          setNotice({ kind: 'weather', message: result.message });
    67	          return;
    68	        default:
    69	          setNotice({ kind: 'error', message: 'Unexpected response from the server.' });
    70	      }
    71	    } catch {
    72	      setNotice({ kind: 'error', message: 'Could not reach the server. Please try again.' });
    73	    }
    74	  }
    75	
    76	  return (
    77	    <form onSubmit={onSubmit} noValidate className="grid gap-5">
    78	      {notice && <NoticeAlert notice={notice} />}
    79	
    80	      <Field id="street" label="Street" error={errors.street}>
    81	        <Input
    82	          id="street"
    83	          value={values.street}
    84	          onChange={(e) => update('street')(e.target.value)}
