   101	
   102	      <div className="grid grid-cols-2 items-start gap-4">
   103	        <Field id="state" label="State" error={errors.state}>
   104	          <NativeSelect
   105	            id="state"
   106	            value={values.state}
   107	            onChange={(e) => update('state')(e.target.value)}
   108	            aria-invalid={!!errors.state}
   109	            aria-describedby={errors.state ? 'state-error' : undefined}
   110	            className="w-full"
   111	          >
   112	            <NativeSelectOption value="">Select…</NativeSelectOption>
   113	            {STATES.map((state) => (
   114	              <NativeSelectOption key={state} value={state}>
   115	                {state}
   116	              </NativeSelectOption>
   117	            ))}
   118	          </NativeSelect>
   119	        </Field>
   120	
   121	        <Field id="zipCode" label="Zip code" error={errors.zipCode}>
   122	          <Input
   123	            id="zipCode"
   124	            value={values.zipCode}
   125	            onChange={(e) => update('zipCode')(e.target.value)}
   126	            placeholder="85268"
   127	            inputMode="numeric"
   128	            maxLength={5}
   129	            aria-invalid={!!errors.zipCode}
   130	            aria-describedby={errors.zipCode ? 'zipCode-error' : undefined}
   131	          />
   132	        </Field>
   133	      </div>
   134	
   135	      <Button type="submit" disabled={loading} className="justify-self-start">
