1530	     1	import { SortDirection, USState } from '@/gql/graphql';
1531	     2	import { NO_FILTER, type FilterValues } from './property-filters';
1532	     3	
1533	     4	/**
1534	     5	 * The list's filters and sort live in the URL (SPEC P1), e.g. `/?city=hills&state=AZ&sort=oldest`,
1535	     6	 * so they survive a reload and can be shared. Defaults are left out to keep URLs short.
1536	     7	 */
1537	     8	export interface ListParams {
1538	     9	  filter: FilterValues;
1539	    10	  direction: SortDirection;
1540	    11	}
1541	    12	
1542	    13	const STATES = new Set<string>(Object.values(USState));
1543	    14	
1544	    15	/**
1545	    16	 * Hand-edited or stale URLs must not break the page: an invalid zip or state is ignored rather
1546	    17	 * than sent to the API, which would reject the whole query (S3.6, S3.7).
1547	    18	 */
1548	    19	export function readListParams(params: URLSearchParams): ListParams {
1549	    20	  const zipCode = params.get('zip')?.trim() ?? '';
1550	    21	  const state = params.get('state') ?? '';
1551	    22	  return {
1552	    23	    filter: {
1553	    24	      ...NO_FILTER,
1554	    25	      city: params.get('city') ?? '',
1555	    26	      zipCode: /^\d{5}$/.test(zipCode) ? zipCode : '',
1556	    27	      state: STATES.has(state) ? state : '',
1557	    28	    },
1558	    29	    direction: params.get('sort') === 'oldest' ? SortDirection.ASC : SortDirection.DESC,
1559	    30	  };
1560	    31	}
1561	    32	
1562	    33	export function writeListParams({ filter, direction }: ListParams): URLSearchParams {
1563	    34	  const params = new URLSearchParams();
1564	    35	  const city = filter.city.trim();
1565	    36	  const zipCode = filter.zipCode.trim();
1566	    37	  if (city) params.set('city', city);
1567	    38	  if (zipCode) params.set('zip', zipCode);
1568	    39	  if (filter.state) params.set('state', filter.state);
1569	    40	  if (direction === SortDirection.ASC) params.set('sort', 'oldest');
1570	    41	  return params;
1571	    42	}
