    19	type Property = PropertiesResult['properties'][number];
    20	
    21	const SORT_LABEL: Record<SortDirection, string> = {
    22	  DESC: 'Newest first',
    23	  ASC: 'Oldest first',
    24	};
    25	
    26	const createdAtFormat = new Intl.DateTimeFormat('en-US', {
    27	  dateStyle: 'medium',
    28	  timeStyle: 'short',
    29	});
    30	
    31	/** S1 list with the S2 sort toggle and S3 filters, both kept in the URL. */
    32	export function PropertyList() {
    33	  const [searchParams, setSearchParams] = useSearchParams();
    34	  const { filter, direction } = readListParams(searchParams);
    35	  const setFilter = (next: FilterValues) =>
    36	    setSearchParams(writeListParams({ filter: next, direction }));
    37	  const setDirection = (next: SortDirection) =>
    38	    setSearchParams(writeListParams({ filter, direction: next }), { replace: true });
    39	  const { data, error, loading, refetch } = useQuery(PropertiesQuery, {
    40	    variables: { filter: toPropertyFilter(filter), orderBy: { createdAt: direction } },
    41	    // The list is unmounted while a property is created, so a named refetch would miss it.
    42	    // Showing the cache and re-fetching on every mount keeps it current (S5.8).
    43	    fetchPolicy: 'cache-and-network',
    44	  });
    45	  const properties = data?.properties;
    46	
    47	  return (
    48	    <section className="grid gap-4">
    49	      <div className="flex items-center justify-between gap-4">
    50	        <h1 className="font-heading text-2xl font-semibold">Properties</h1>
    51	        <Button
    52	          variant="outline"
    53	          size="sm"
    54	          onClick={() =>
    55	            setDirection(direction === SortDirection.DESC ? SortDirection.ASC : SortDirection.DESC)
    56	          }
    57	          aria-label={`Sorted by creation date: ${SORT_LABEL[direction]}. Change order`}
    58	        >
    59	          <ArrowDownUp />
    60	          {SORT_LABEL[direction]}
    61	        </Button>
    62	      </div>
    63	
    64	      <PropertyFilters applied={filter} onApply={setFilter} />
    65	
    66	      {error && !properties ? (
    67	        <Alert variant="destructive">
    68	          <AlertTitle>Could not load properties</AlertTitle>
    69	          <AlertDescription className="grid gap-2">
    70	            <span>Check that the API is running, then try again.</span>
    71	            <Button
    72	              variant="outline"
    73	              size="sm"
    74	              className="justify-self-start"
    75	              onClick={() => void refetch()}
    76	            >
    77	              Retry
    78	            </Button>
    79	          </AlertDescription>
    80	        </Alert>
    81	      ) : !properties && loading ? (
    82	        <PropertyListSkeleton />
    83	      ) : properties?.length === 0 && isFiltering(filter) ? (
    84	        <Card>
    85	          <CardContent className="grid justify-items-center gap-2 py-8 text-center">
    86	            <p className="font-medium">No properties match these filters</p>
    87	            <Button variant="outline" size="sm" onClick={() => setFilter(NO_FILTER)}>
    88	              Clear filters
    89	            </Button>
    90	          </CardContent>
    91	        </Card>
    92	      ) : properties?.length === 0 ? (
    93	        <Card>
    94	          <CardContent className="grid gap-2 py-8 text-center">
    95	            <p className="font-medium">No properties yet</p>
    96	            <p className="text-muted-foreground">
    97	              <Link to="/properties/new" className="underline">
    98	                Add a property
    99	              </Link>{' '}
   100	              to record it with its current weather.
   101	            </p>
   102	          </CardContent>
   103	        </Card>
   104	      ) : (
   105	        <ul className="grid gap-3" aria-label="Properties">
   106	          {properties?.map((property) => (
   107	            <li key={property.id}>
   108	              <PropertyRow property={property} />
   109	            </li>
   110	          ))}
   111	        </ul>
   112	      )}
   113	    </section>
   114	  );
   115	}
