  console.log(`[${new Date().toISOString()}] archived ${base}: ${written.length} files`);
  if (leaks.length) {
    for (const l of leaks) console.error(`LEAK ${l.kind} in ${l.file}: …${l.sample}…`);
    process.exitCode = 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === SELF) {
